<?php
require_once dirname(__DIR__).'/includes/bootstrap.php';
$user=club_require_login();$id=isset($_GET['id'])?(int)$_GET['id']:null;$row=$id?club_community_record('event',$id):null;
if(($id&&(!$row||!club_content_editable($row)))||(!$id&&!club_can('content.submit')&&!club_can('content.publish'))){http_response_code(403);exit('You cannot edit this event.');}
$values=$row??['title'=>'','description'=>'','event_date'=>date('Y-m-d'),'end_date'=>'','start_time'=>'','end_time'=>'','venue'=>'Nettlebed Village Club','booking_link'=>'','visibility'=>'public','recurrence'=>'none','recurrence_end_date'=>''];$error='';$pendingRevisionId=null;
if($id&&$row['status']==='published'){$s=db()->prepare("SELECT id,payload FROM club_revisions WHERE owner_type='event' AND owner_id=? AND status='submitted' ORDER BY id DESC LIMIT 1");$s->execute([$id]);if($pending=$s->fetch()){$pendingRevisionId=(int)$pending['id'];$values=array_merge($values,json_decode($pending['payload'],true));}}
$values['description']=html_entity_decode(strip_tags(str_replace(['<br>','<br/>','<br />'],"\n",$values['description']??'')),ENT_QUOTES,'UTF-8');
if($_SERVER['REQUEST_METHOD']==='POST'){
    csrf_verify();$values=array_merge($values,$_POST);
    try{
        if(($_POST['action']??'')==='cancel') {club_cancel_event((int)$id,(string)($_POST['scope']??''),$_POST['occurrence_date']??null,(string)($_POST['reason']??''));flash_success('The calendar has been updated.');redirect('/members/posts.php');}
        $saved=club_content_save('event',$id,$_POST,($_POST['action']??'')==='submit',$_FILES['attachments']??[]);
        flash_success($saved['status']==='submitted'?'Your event is awaiting committee approval.':'Your event draft has been saved.');redirect('/members/posts.php');
    }catch(Throwable $e){$error=$e->getMessage();}
}
club_member_layout_start($id?'Edit event':'Add an event');
?>
<p>Bring people together. The committee reviews each event before it appears on the calendar.</p><?php flash_render();if($error): ?><p class="alert alert--error" role="alert"><?= e($error) ?></p><?php endif ?><?php if($row&&$row['status']==='published'): ?><div class="platform-panel"><p>The approved event stays on the calendar. Changes create a revision for committee approval.</p></div><?php endif ?>
<form method="post" enctype="multipart/form-data" class="platform-panel"><?php csrf_field(); ?>
<div class="form-field"><label for="title">Event title</label><input id="title" name="title" required maxlength="190" value="<?= e($values['title']) ?>"></div>
<div class="form-field"><label for="description">Tell us about the event</label><textarea id="description" name="description" rows="7" required maxlength="50000"><?= e($values['description']) ?></textarea></div>
<div class="platform-grid"><div class="form-field"><label for="event_date">Start date</label><input id="event_date" type="date" name="event_date" required value="<?= e($values['event_date']) ?>"></div><div class="form-field"><label for="end_date">End date (optional)</label><input id="end_date" type="date" name="end_date" value="<?= e($values['end_date']) ?>"></div></div>
<div class="form-field"><label><input type="checkbox" name="all_day" value="1"<?= empty($values['start_time'])?' checked':'' ?>> All day</label></div>
<div class="platform-grid"><div class="form-field"><label for="start_time">Starts</label><input id="start_time" type="time" name="start_time" value="<?= e(substr($values['start_time']??'',0,5)) ?>"></div><div class="form-field"><label for="end_time">Ends</label><input id="end_time" type="time" name="end_time" value="<?= e(substr($values['end_time']??'',0,5)) ?>"></div></div><p class="text-muted">UK time. For overnight events, choose the following end date or an earlier end time.</p>
<div class="platform-grid"><div class="form-field"><label for="venue">Venue</label><input id="venue" name="venue" maxlength="190" value="<?= e($values['venue']) ?>"></div><div class="form-field"><label for="visibility">Who can see it?</label><select id="visibility" name="visibility"><option value="public"<?= $values['visibility']==='public'?' selected':'' ?>>Public — everyone welcome</option><option value="members"<?= $values['visibility']==='members'?' selected':'' ?>>Members only</option></select></div></div>
<div class="form-field"><label for="booking_link">Booking / information link (optional)</label><input id="booking_link" type="url" name="booking_link" maxlength="255" value="<?= e($values['booking_link']) ?>" placeholder="https://"></div>
<div class="platform-grid"><div class="form-field"><label for="recurrence">Repeat</label><select id="recurrence" name="recurrence"><?php foreach(['none'=>'One event','weekly'=>'Every week','monthly'=>'Every month on this date'] as $key=>$label): ?><option value="<?= $key ?>"<?= $values['recurrence']===$key?' selected':'' ?>><?= $label ?></option><?php endforeach ?></select></div><div class="form-field"><label for="recurrence_end_date">Last repeat date</label><input id="recurrence_end_date" type="date" name="recurrence_end_date" value="<?= e($values['recurrence_end_date']) ?>"></div></div><p class="text-muted">Monthly events skip months without the chosen date, for example the 31st.</p>
<div class="form-field"><label for="attachments">Photographs or documents</label><input id="attachments" type="file" name="attachments[]" multiple data-club-upload accept="image/jpeg,image/png,image/webp,image/heic,image/heif,.pdf,.docx,.xlsx"><small>Up to three attachments; photos up to 30 MB are reduced automatically. PDF, Word and Excel are supported.</small></div>
<div class="hero__actions"><?php if(!$row||$row['status']!=='published'): ?><button class="btn btn--secondary" name="action" value="draft">Save draft</button><?php endif ?><button class="btn btn--primary" name="action" value="submit">Submit for approval</button><a href="<?= e(site_url('/members/posts.php')) ?>">Cancel</a></div></form>
<?php if($id): ?><h2>Saved attachments</h2><?php club_content_attachments('event',$id); ?><?php endif ?>
<?php if($row&&$row['status']==='published'&&club_can('content.publish')): ?><form method="post" class="platform-panel"><?php csrf_field(); ?><h2>Cancel event</h2><p>Remove one date or withdraw the whole series from the calendar.</p><div class="form-field"><label for="scope">Cancel</label><select id="scope" name="scope"><option value="occurrence">One occurrence</option><option value="series">Whole event / series</option></select></div><div class="form-field"><label for="occurrence_date">Occurrence date</label><input id="occurrence_date" name="occurrence_date" type="date" value="<?= e($row['event_date']) ?>"></div><div class="form-field"><label for="reason">Reason</label><input id="reason" name="reason" required maxlength="1900"></div><button class="btn btn--secondary" name="action" value="cancel">Confirm cancellation</button></form><?php endif ?>
<?php if($pendingRevisionId): ?><h2>Proposed attachments awaiting approval</h2><?php club_content_attachments('revision',$pendingRevisionId); ?><?php endif ?>
<?php club_member_layout_end(); ?>
